namespace EBR.Infrastructure.Evaluations;

/// <summary>Nodo del árbol de la ficha, con la celda de la que se copió su texto.</summary>
public sealed record BpmTemplateNode(string Code, string? ParentCode, string ItemType, string Description, string SourceCell);

/// <summary>Criterio de la guía de llenado con su marca de criticidad tal como aparece en la hoja.</summary>
public sealed record BpmGuidanceEntry(string ItemCode, string Code, string Description, string? CriticalityMark, string SourceCell);

/// <summary>Banda de calificación de la ficha.</summary>
public sealed record BpmQualificationBand(
    string Code,
    string Description,
    string Classification,
    string Action,
    decimal? MinPercentage,
    bool MinIncluded,
    decimal? MaxPercentage,
    bool MaxIncluded,
    string SourceCell);

