        new("1.2.3.b", "iii", "iii. Las puertas no abren directamente hacia el área de proceso.", null, "D160"),
        new("1.2.3.c", "i", "i. Los vestidores se mantienen limpios.", null, "D162"),
        new("1.2.3.c", "ii", "ii. Los casilleros se mantienen en buen estado.", null, "D163"),
        new("1.2.3.c", "iii", "iii. Los espejos y asientos se mantien en buen estado", null, "D164"),
        new("1.2.4.a", "i", "i. El equipo utilizado para cocer, calentar, enfriar, refrigerar, congelar o almacenar alimentos está diseñado de modo que el alimento alcance la temperatura requerida con la mayor rapidez posible y la mantene de manera eficaz.", "C", "D170"),
        new("1.2.4.a", "ii", "ii.  El establecimiento cuenta con un sistema adecuado para controlar el tiempo y la temperatura durante la cocción, el enfriamiento, la refrigeración, la congelación y el almacenamiento.", "C", "D174"),
        new("1.2.4.a", "iii", "iii. En el sistema se especifica con claridad los límites tolerables para las variaciones de tiempo y temperatura.", "C", "D177"),
        new("1.2.4.a", "iv", "iv. Los equipos utilizados para monitorear y controlar el tiempo y la temperatura son sometidos a procesos de mantenimiento y calibración de acuerdo a lo especificado por el fabricante.", "M", "D179"),
        new("1.2.4.a", "v", "v. El establecimiento mantiene los registros escritos del monitoreo y control del tiempo y temperatura y del mantenimiento y calibración de los equipos.", "M", "D182"),
        new("1.2.4.b", "i", "i. En el sistema se especifica con claridad los límites tolerables para las variaciones de tiempo y temperatura.", null, "D188"),
        new("1.2.4.b", "ii", "ii, Cuenta con medios para monitorear, controlar y dar seguimiento a la temperatura y humedad.", null, "D190"),
        new("1.2.5.a", "i", "i. El sistema de ventilación reduce al mínimo la contaminación de los alimentos transmitida por el aire.", null, "C193"),
        new("1.2.5.a", "ii", "ii. El sistema de ventilación contribuye con el control de la temperatura ambiente.", null, "C195"),
        new("1.2.5.a", "iii", "iii. El sistema de ventilación contribuye con el contro de los olores y la humedad para garantizar la inocuidad y la idoneidad de los alimentos.", null, "C197"),
        new("1.2.6", "i", "i. La iluminación debe ser suficiente para detectar defectos o contaminantes en los alimentos, o de examinar las instalaciones y el equipo para comprobar su limpieza.", null, "C200"),
        new("1.2.6", "ii", "ii. La intensidad debe ser suficiente para la naturaleza de la actividad que se realice.", null, "C203"),
        new("1.2.6", "iii", "iii, Cuando corresponda, las luminarias  están protegidas, , para garantizar que los alimentos no se contaminen en caso de rotura de los elementos de iluminación.", null, "C205"),
        new("1.2.7.a", "i", "i. Las instalaciones de almacenamiento faciliten un mantenimiento y una limpieza adecuados.", "m", "C209"),
        new("1.2.7.a", "ii", "ii. Las instalaciones de almacenamiento eviten el acceso y el anidamiento de plagas.", "C", "C211"),
        new("1.2.7.a", "iii", "iii. Las instalaciones de almacenamiento permiten que los alimentos estén protegidos eficazmente de la contaminación, incluido el contacto cruzado con alérgenos.", "M", "C213"),
        new("1.2.7.a", "iv", "iv.  Las instalaciones de almacenamiento cuentan con medios para el control de la temperatura y humedad, cuando aplique.", "C", "C216"),
        new("1.3.a", "i", "i. El equipo y los recipientes están fabricados con materiales que no sean potencialmente tóxicos para el uso al que se destinan.", "C", "B219"),
        new("1.3.a", "ii", "ii. Están diseñados, fabricados y ubicados de manera que se puedan limpiar y desinfectar adecuadamente.", "C", "B221"),
        new("1.3.a", "iii", "iii. Están instalados de manera que se facilite su mantenimiento.", "m", "B223"),
        new("2.1.a", "i", "i. El personal cuenta con los conocimientos y capacidades necesarios para poder manipular los alimentos en condiciones higiénicas.", null, "B227"),
        new("2.1.a", "ii", "ii. El personal que manipula alimentos  ha sido capacitado en el uso adecuado  productos químicos de limpieza u otras sustancias químicas potencialmente peligrosas para evitar la contaminación de los alimentos.", null, "B229"),
        new("2.2.a", "i", "i. El programa contempla la naturaleza de los peligros asociados con los alimentos, por ejemplo, su capacidad para favorecer la proliferación de microorganismos patógenos o que causen deterioro, la existencia de posibles contaminantes físicos o alérgenos conocidos.", null, "B233"),
        new("2.2.a", "ii", "ii. La manera en que se elaboran, manipulan, envasan y almacenan los alimentos, incluida la probabilidad de contaminación.", null, "B237"),
        new("2.2.a", "iii", "iii. El tiempo que se prevé que transcurra antes del consumo del alimento.", null, "B239"),
        new("2.2.a", "iv", "iv. El uso y el mantenimiento de los utensilios y el equipo relacionados con los alimentos.", null, "B240"),
        new("2.2.a", "v", "v. El programa de capacitación se revisa rutinariamente y se actualiza cuando sea necesario.", null, "B242"),
        new("2.3.a", "i", "i.Se realizan evaluaciones periódicas de la eficacia de los programas de capacitación e instrucción.", "m", "B245"),
        new("2.3.a", "ii", "ii. Se garantiza que los procedimientos se  realizan de forma adecuada por medio de supervisiones y verificaciones rutinarias.", "M", "B247"),
        new("2.3.a", "iii", "iii.  El personal encargado del control de los alimentos está capacitado adecuadamente para las runciones que realiza", "C", "B249"),
        new("3.1.1.a", "i", "i. En las zonas de preparación y almacenamiento de alimentos se utilizan productos de limpieza especializados para superficies que entran en contacto con los alimentos.", "m", "C255"),
        new("3.1.1.a", "ii", "ii. Los productos químicos para la limpieza y desinfección se  manejan y utilizan según las instrucciones de los fabricantes", "M", "C258"),
        new("3.1.1.a", "iii", "iii. El equipo de limpieza se almacena en un lugar adecuado y de modo tal que se evite la contaminación.", "M", "C260"),
        new("3.1.2.a", "i", "i. El establecimiento cuenta con procedimientos escritos de limpieza y desinfección (POES)", "C", "C263"),
        new("3.1.2.a", "ii", "ii. Los procedimientos de limpieza no provocan la contaminación de los alimentos,", null, "C265"),
        new("3.1.2.a", "iii", "iii. La concentración y el tiempo de aplicación de los productos químicos utilizados para la desinfección se emplean según las instrucciones del fabricante.", null, "C267"),
        new("3.1.3.a", "i", "i. Se toman medidas para tomar muestras y hacer pruebas del medio ambiente y de las superficies que entran en contacto con los alimentos.", "M", "C271"),
        new("3.1.3.a", "ii", "ii. En los casos que no proceda tomar muestras para realizar análisis microbiológicos, se monitorean los procedimientos de limpieza y desinfección, incluida la concentración correcta de desinfectante para asegurarse que se siguen los protocolos de forma adecuada.", "M", "C273"),
        new("3.1.3.a", "iii", "iii. Los procedimientos de limpieza y desinfección y de mantenimiento se revisan periódicamente, se adaptan para reflejar cualquier cambio de circunstancias y se documentan como corresponda.", "M", "C277"),
        new("3.2.a", "i", "i. El establecimiento y las áreas circundantes se inspeccionan de forma regular para detectar indicios de infestación.", null, "B281"),
        new("3.2.a", "ii", "ii. El programa contempla medidas de erradicación en caso de alguna invasión de plaga.", "M", "B283"),
        new("3.2.a", "iii", "iii. Los productos químidos utilizados son autorizados y no suponen una amenaza para la inocuidad o la idoneidad de los alimentos.", "M", "B285"),
        new("4.a", "i", "i. Al personal que presente síntomas o que  se sabe o sospeche que padece o es portador de alguna enfermedad que probablemente se transmita por medio de los alimentos no se le permite ingresar a ninguna área de manipulación de alimentos.", "C", "B289"),
        new("4.a", "ii", "ii. El personal mantiene un alto nivel de aseo personal y, cuando corresponda, utiliza ropa protectora, cubre cabezas, cubre barba, mascarilla y calzado adecuado.", "C", "B293"),
        new("4.a", "iii", "iii. Se aplican medidas para evitar la contaminación cruzada por parte del personal, a través de un correcto lavado de manos y, cuando procedaa, mediante el uso de guantes,", "C", "B296"),
        new("4.a", "iv", "iv. El persobnal que manipula alimentos debe evitar conductas que puedan contaminar los alimentos tales como:, fumar, vapear, escupir, comer, beber, estornudar, tocer, tocarse la boca o la nariz, etc.", null, "B299"),
        new("4.a", "v", "v. El personal que manipula alimentos no debe portar joyas, relojes, prendedores, cadenas, etc., al igual que pestañas y uñas postizas.", null, "B302"),
        new("4.a", "vi", "vi. El personal que visita el área de producción al igual que el personal de mantenimiento, debe llevar ropa protectora y cumplir con todos los requisitos exigidos a los manipuladores de alimentos..", null, "B304"),
        new("5.1.1.a", "i", "i. Se especifica el uso previsto del alimento", "m", "C311"),
        new("5.1.1.a", "ii", "ii. Se especifica si los productos están destinados a grupos de consumidores vulnerables.", "M", "C312"),
        new("5.1.1.a", "iii", "iii. Se especifica la composición de los ingredientes, Aw, pH y método de conservación.", "m", "C314"),
        new("5.1.1.a", "iv", "iv. Se espesifica la presencia de alérgenos", "C", "C316"),
        new("5.1.1.a", "v", "v. Se especifica cualquier límite pertinente establecido para el alimento por la autoridad competente o, en ausencia de esta, por la gerencia del establecimiento.", "M", "C317"),
        new("5.1.1.a", "vi", "vi. Se describen las instrucciones para su uso ulterior", "m", "C320"),
        new("5.1.1.a", "vii", "vii, Se especifican las condiciones necesarias de almacenamiento", null, "C321"),
        new("5.1.1.a", "viii", "viii. Se especifican los materiales de envasado utilizados para los alimentos", "m", "C322"),
        new("5.1.2.a", "i", "i. Los diagramas de flujo contienen todas las fases de las actividades relativas a cada uno de los producto o línea de productos.", null, "C325"),
        new("5.1.2.a", "ii", "ii. Los diagramas de flujo muestran la secuencia y la interacción de todas las fases de la operación, incluidos los momentos en que las materias primas, ingredientes y productos intermedios se incorporan al flujo y cuándo se liberan y retiran los productos intermedios, subproductos y residuos.", null, "C327"),
        new("5.1.2.a", "iii", "iii. Los parámetros de control de las fases claves de producción de alimentos que contribuyen a la inocuidad tales como cocción, enfriado, congelado son monitoreados y sujetos a seguimiento.", "C", "C332"),
        new("5.1.3.a", "i", "i. Cuando se detectan no conformimades se toman las medidas correctivas de lugar.", "C", "C336"),
        new("5.1.3.a", "ii", "ii. El establecimiento realiza actividades de verificación de la efectividad y buena aplicación de los POE y los POES.", "M", "C338"),
        new("5.1.3.a", "iii", "iii. El establecimiento mantiene registros escritos sobre los hallazgos durante el monitoreo, sobre las medidas correctivas aplicadas y de las actividades de verificación durante un período superior a la vida útil del producto o durante el tiempo que establezca la autoridad competente.", "M", "C340"),
        new("5.2.1.a", "i", "i. Las especificaciones establecen los parámetros de muestreo, los métodos analíticos, los límites aceptables, y los procedimientos de monitoreo y seguimiento.", "m", "C347"),
        new("5.2.1.a", "ii", "ii.  Los alimentos crudos, que no se consideran listos para consumo, estan separados de los alimentos listos para el consumo.", "M", "C350"),
        new("5.2.1.a", "iii", "iii. Las áreas de elaboración donde existe un mayor riesgo de contaminación del alimento están debidamente indentificadas para restringir el acceso a las mismas", "M", "C352"),
        new("5.2.1.a", "iv", "iv. El establecimiento tiene implementado un sistema para impedir la contaminación fisica de los alimentos (tales como detectores de metales o detectores de rayos X).", "C", "C355"),
        new("5.2.1.a", "v", "v. Los productos de limpieza y desinfección al igual que los plaguicidas se  identifican, almacenan y se utilizan de forma segura a fin de evitar la contaminación de los alimentos, las superficies de contacto  y los materiales de envasado de alimentos.", "M", "C358"),
        new("5.2.1.a", "vi", "vi. Se llevan controles sobre los aditivos alimentarios y los coadyuvantes de elaboración cuyo uso inadecuado pudiera resultar perjudicial, a fin de que se utilicen únicamente de la manera prevista.", "M", "C362"),
        new("5.2.1.a", "vii", "vii. El establecimiento tiene identificados los alimentos que tienen carácter de alérgenos y dicha información está expresada claramente en las etiquetas de los mismos, para conocimiento de los consumidores.", "C", "C365"),
        new("5.2.1.a", "viii", "viii. El establecimiento  tiene implementado controles para prevenir la contaminación cruzada entre alimentos que contienen alérgenos y otros alimentos que no lo contienen.", "C", "C368"),
        new("5.2.1.a", "ix", "ix. Cuando existe riesgo de que los alimentos que no contienen alérgenos pueden contener trazas de los mismos, se declara en la etiqueta para el conocimiento de los consumidores.", "C", "C371"),
        new("5.2.2.a", "i", "i. Se realizan inspecciones visuales de las materias primas (deterioro, fecha de vencimiento, alérgenos declarados, etc) , o se hacen mediciones de temperatura (para productos refrigerados o cangelados), para tomas las medidas adecuadas antes de la elaboración", null, "C375"),
        new("5.2.2.a", "ii", "ii. Cuando corresponda, se realizan pruebas de laboratorio para comprobar la inocuidad e idoneidad de las materias primas o ingredientes.", null, "C379"),
        new("5.2.2.a", "iii", "iii. Existe documentación y registro sobre las informaciones relevantes de los certificados de análisis, información del proveedor, fecha de recepción, cantidades,  etc.", null, "C382"),
        new("5.2.3.a", "i", "i. El diseño y el material del envasado permite el etiquetado adecuando del alimento.", null, "C386"),
        new("5.2.3.a", "ii", "ii. Cuando se utilicen gases para el envasado, se cuenta con la evidencia documental sobre la inocuidad de dichos materiales.", null, "C388"),
        new("5.2.3.a", "iii", "iii. El material de envasado reutilizable tiene una duración adecuada, es fácil de limpiar y, en caso necesario, de desinfectar.", null, "C390"),
        new("5.3.a", "i", "i. El establecimiento mantiene el control y registro de la potabilidad del agua.", "C", "B394"),
        new("5.3.a", "ii", "ii. El agua y hielo utilizados para la elaboradión de los alimentos son potables.", "C", "B395"),
        new("5.3.a", "iii", "iii. El agua y el hielo se almacenan y manipulan de manera que no se contaminen.", "C", "B396"),
        new("5.3.a", "iv", "iv. La generación de vapor que entra en contacto con los alimentos no da lugar a su contaminación.", "C", "B398"),
        new("5.3.a", "v", "v. El agua que no es apta para el uso en contacto con los alimentos tiene un sistema separado que no contamina el sistema de agua potable.", "M", "B400"),
        new("5.3.a", "vi", "vi. El agua recirculada para su reutilización y el agua recuperada de las operaciones de elaboración de alimentos por evaporación o por filtración, se trata para asegurar que  no comprometa la inocuidad e idoneidad de los alimentos.", "M", "B402"),
        new("5.4.a", "i", "i. Los procedimientos permiten la rápida y eficaz identificación y el retiro completo del mercado de cualquier alimento que pueda suponer un riesgo para la salud pública.", "M", "C409"),
        new("5.4.a", "ii", "ii. Los procedimientos permiten la devolución por parte de los consumidores de cualquier alimento que pueda suponer un riesgo para la salud pública.", "m", "C412"),
        new("5.4.a", "iii", "iii. Los procedimientos contemplan evaluar los demás lotes de productos elaborados en condiciones similares a los  que se han retirado del mercado para determinar si son inocuos y seguros.", "m", "C415"),
        new("5.4.a", "iv", "iv. Los procedimientos permiten informar a la autoridad competente y emitir alertas públicas cuando el producto pueda haber llegado a los consumidores y sea necesario su devolución o retiro del mercado.", "M", "C418"),
        new("5.4.a", "v", "v. Los procedimientos para retirar alimentos del mercado se revisan y actualizan cuando sea necesario, a partir de los resultados de simulacros periódicos.", "m", "C421"),
        new("5.4.a", "vi", "vi. El establecimiento conserva la documentación escrita con la información de la causa y el alcance de un retiro del mercado y las medidas correctivas adoptadas.", "m", "C424"),
        new("5.4.b", "i", "i. Se almacenan hasta que se destruyan", null, "C428"),
        new("5.4.b", "ii", "ii. Se mantienen almacenados hasta que se utilicen con fines distintos del consumo humano", null, "C429"),
        new("5.4.b", "iii", "iii. Se mantienen almacenados hasta que se determine su inocuidad para el consumo humano", null, "C431"),
        new("5.4.b", "iv", "iv. Se mantienen almacenados hasta que se reelaboren de manera que se reduzca el peligro a niveles aceptables y la autoridad competente lo permita", null, "C433"),
        new("6.1.a", "i", "i. Las etiquetas muestran el Nombre de los productos", "m", "B438"),
        new("6.1.a", "ii", "ii. Las etiquetas muestran la lista de Ingredientes", "C", "B439"),
        new("6.1.a", "iii", "iii. Las etiquetas muestran el contenido neto y peso escurrido", "m", "B440"),
        new("6.1.a", "iv", "iv. Las etiquetas muestran el nombre y dirección del fabricante", "m", "B441"),
        new("6.1.a", "v", "v Las etiquetas muestran el Registros Sanitario", "M", "B442"),
        new("6.1.a", "vi", "vi. Las etiquetas muestran el país de origen", "m", "B443"),
        new("6.1.a", "vii", "vii. Las etiquetas muestran la identificación del lote", "M", "B444"),
        new("6.1.a", "viii", "viii. Las etiquetas muestran la fecha de vencimiento", "m", "B445"),
        new("6.1.a", "ix", "ix. Las etiquetas muestran las instrucciones para la conservación", "M", "B446"),
        new("6.1.a", "x", "x. Las etiquetas muestran las instrucciones para el uso", "M", "B447"),
        new("6.1.a", "xi", "xi. Las etiquetas muestran la declaración de alérgenos", "C", "B448"),
        new("7.a", "i", "i. Los medios de transporte están diseñados de tal manera que permiten una separación eficaz entre los distintos alimentos y/o entre otros alimentos y los articulos no alimentarios que podrian causar contaminación.", null, "B452"),
        new("7.a", "ii", "ii. Ofrecen  una protección eficaz contra la contaminación, incluidos el polvo y el humo.", null, "B455"),
        new("7.a", "iii", "iii. Los medios de transporte se mantienen en un estado adecuado de limpieza, reparación y mantenimiento.", null, "B457"),
        new("7.a", "iv", "iv. Cuando el medio de transporte se utiliza para transportar diferentes tipos de alimentos o productos no alimentarios, están definidos los controles de limpieza, desinfección y secado entre cada carga.", null, "B459"),
        new("7.a", "v", "v. Las operaciones de carga y descarga deben realizarse fuera de las áreas de producción.", null, "B462"),
        new("7.a", "vi", "vi. Se mantienen los registros de las actividades de limpieza y desinfección de los medios de tranporte.", null, "B464"),
        new("7.a", "vii", "vii. El personal que realiza el transporte está capacitado en la adecuada manipulación de los alimentos que transporta y en las medidas precautorias para asegurar su inocuidad.", null, "B466")
    ];
}
